using QuestPDF.Fluent;using QuestPDF.Helpers;using QuestPDF.Infrastructure;using UAF.Application.Features.Documents;
namespace UAF.Infrastructure.Documents;
public sealed class QuestPdfUniversityDocumentGenerator:IUniversityDocumentPdfGenerator{
 public QuestPdfUniversityDocumentGenerator()=>QuestPDF.Settings.License=LicenseType.Community;
 public byte[] GenerateAdmissionLetter(string universityName,string applicationNumber,string applicantName,string programName,DateOnly issueDate)=>Document.Create(d=>d.Page(p=>{p.Size(PageSizes.A4);p.Margin(42);p.DefaultTextStyle(x=>x.FontSize(11));p.Header().Column(c=>{c.Item().AlignCenter().Text(universityName).FontSize(20).Bold();c.Item().AlignCenter().Text("OFFICIAL ADMISSION LETTER").FontSize(15).Bold();});p.Content().PaddingTop(35).Column(c=>{c.Spacing(14);c.Item().AlignRight().Text($"Date: {issueDate:dd MMM yyyy}");c.Item().Text($"Application No: {applicationNumber}").Bold();c.Item().Text($"Dear {applicantName},");c.Item().Text($"We are pleased to inform you that your application has been accepted for admission to {programName}.");c.Item().Text("Please follow the university's published registration, document submission and fee payment instructions to complete your admission.");c.Item().PaddingTop(30).Text("Admissions Office").Bold();c.Item().Text(universityName);});p.Footer().AlignCenter().Text("This letter was generated electronically by the University Management System.");})).GeneratePdf();
 public byte[] GenerateFeeChallan(string universityName,string number,string student,string registration,DateOnly issue,DateOnly due,string currency,decimal subtotal,decimal lateFee,IReadOnlyList<FeeChallanPdfLine> lines)=>Document.Create(d=>d.Page(p=>{p.Size(PageSizes.A4);p.Margin(30);p.DefaultTextStyle(x=>x.FontSize(9));p.Header().Column(c=>{c.Item().AlignCenter().Text(universityName).FontSize(18).Bold();c.Item().AlignCenter().Text("FEE CHALLAN").FontSize(14).Bold();});p.Content().Column(c=>{c.Spacing(7);c.Item().Text($"Challan: {number}").Bold();c.Item().Text($"Student: {student}");c.Item().Text($"Registration: {registration}");c.Item().Text($"Issue date: {issue:dd MMM yyyy}    Due date: {due:dd MMM yyyy}");c.Item().Table(t=>{t.ColumnsDefinition(x=>{x.RelativeColumn(1);x.RelativeColumn(3);x.RelativeColumn(1);});t.Header(h=>{h.Cell().Background(Colors.Grey.Lighten2).Padding(5).Text("Code").Bold();h.Cell().Background(Colors.Grey.Lighten2).Padding(5).Text("Fee head").Bold();h.Cell().Background(Colors.Grey.Lighten2).Padding(5).AlignRight().Text("Amount").Bold();});foreach(var line in lines){t.Cell().Padding(4).Text(line.Code);t.Cell().Padding(4).Text(line.Name);t.Cell().Padding(4).AlignRight().Text(line.Amount.ToString("N2"));}});c.Item().AlignRight().Text($"Subtotal: {currency} {subtotal:N2}");c.Item().AlignRight().Text($"Late fee: {currency} {lateFee:N2}");c.Item().AlignRight().Text($"Total due: {currency} {subtotal+lateFee:N2}").Bold().FontSize(12);c.Item().PaddingTop(15).Text("Keep this challan and the payment receipt for your records.");});p.Footer().AlignCenter().Text("Generated electronically. Verify payment status through the university finance office.");})).GeneratePdf();
}
